<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
use App\Services\RuleConfigurationService;use App\Services\SportsRulesService;use App\Services\StandingsService;use App\Support\Database;
$db=Database::connection();$db->beginTransaction();try{$tag='rules-'.bin2hex(random_bytes(3));$add=function(string $t,array $d)use($db):int{$d['created_at']=date('Y-m-d H:i:s');$d['updated_at']=date('Y-m-d H:i:s');$s=$db->prepare('INSERT INTO `'.$t.'` (`'.implode('`,`',array_keys($d)).'`) VALUES('.implode(',',array_fill(0,count($d),'?')).')');$s->execute(array_values($d));return(int)$db->lastInsertId();};
$org=$add('organizations',['name'=>$tag,'slug'=>$tag]);$project=$add('projects',['organization_id'=>$org,'name'=>$tag,'slug'=>$tag.'p']);$tid=$add('tournaments',['project_id'=>$project,'name'=>$tag,'slug'=>$tag.'t','season'=>'2026']);$rules=RuleConfigurationService::copaBrasilPreset();$rules['points']=['win'=>5,'draw'=>2,'loss'=>0,'walkover_score'=>'4-0'];$rules['discipline']['yellow_limit']=2;$db->prepare('INSERT INTO tournament_rule_versions(tournament_id,version_number,settings_json,change_reason,is_active,created_at) VALUES(?,1,?,"test",1,NOW())')->execute([$tid,json_encode($rules)]);
$stage=$add('stages',['tournament_id'=>$tid,'name'=>'Groups','stage_key'=>'group','stage_order'=>1,'status'=>'published']);$group=$add('groups_competition',['stage_id'=>$stage,'name'=>'A','group_code'=>'A','group_order'=>1,'max_teams'=>3,'status'=>'published']);$teams=[];for($n=0;$n<3;$n++){$teams[]=$add('teams',['project_id'=>$project,'name'=>$tag.$n,'short_name'=>'T'.$n]);$add('team_tournament_entries',['tournament_id'=>$tid,'team_id'=>$teams[$n],'status'=>'approved']);$add('group_team_assignments',['group_id'=>$group,'team_id'=>$teams[$n],'display_order'=>$n+1,'status'=>'active']);}$person=$add('people',['full_name'=>$tag,'person_type'=>'athlete','status'=>'active']);$add('registrations',['tournament_id'=>$tid,'team_id'=>$teams[0],'person_id'=>$person,'registration_type'=>'athlete','status'=>'approved']);$match=$add('matches',['tournament_id'=>$tid,'stage_id'=>$stage,'group_id'=>$group,'home_team_id'=>$teams[0],'away_team_id'=>$teams[1],'status'=>'scheduled']);
$sports=new SportsRulesService($db);$sports->applyWalkover($match,$teams[0],'absence',null);$rows=(new StandingsService($db))->forGroup($tid,$group);if((int)$rows[0]['points']!==5)throw new RuntimeException('configured W.O. points failed');$penalty=$sports->applyPenalty($tid,$teams[0],-2,'points','test',null);$rows=(new StandingsService($db))->forGroup($tid,$group);if((int)$rows[0]['points']!==3)throw new RuntimeException('points penalty failed');$sports->revokePenalty($penalty,'appeal',null);
$sports->recordCard($match,$teams[0],$person,'yellow',null);$sports->recordCard($match,$teams[0],$person,'yellow',null);$s=$db->prepare('SELECT id FROM suspensions WHERE tournament_id=? AND person_id=? AND status="active"');$s->execute([$tid,$person]);if(!$s->fetchColumn())throw new RuntimeException('yellow suspension failed');try{$sports->assertLineupAllowed($match,$teams[0],[$person]);throw new RuntimeException('lineup not blocked');}catch(RuntimeException $e){if($e->getMessage()!=='Atleta suspenso.')throw$e;}$sports->serveSuspensions($match);$s=$db->prepare('SELECT status FROM suspensions WHERE tournament_id=? AND person_id=? ORDER BY id DESC LIMIT 1');$s->execute([$tid,$person]);if($s->fetchColumn()!=='served')throw new RuntimeException('suspension fulfillment failed');$db->rollBack();echo "SPORTS_RULES_E2E_OK\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
